        }

        [Fact]
        public async Task ShouldPromptForActivationAsync_ShouldReturnTrue_WhenPalierReached()
        {
            // Arrange
            var mockSettings = new Mock<IAppSettingsRepository>();
            var mockState = new Mock<IHistoryStateRepository>();

            mockSettings.Setup(s => s.GetSettingAsync(ShadowModeService.AutoWriteSettingKey))
                        .ReturnsAsync("false");

            mockState.Setup(s => s.GetStateAsync(ShadowModeService.MatchCountStateKey)).ReturnsAsync("300");
            mockState.Setup(s => s.GetStateAsync(ShadowModeService.CategoryCountStateKey)).ReturnsAsync("30");
            mockState.Setup(s => s.GetStateAsync(ShadowModeService.LastPromptMatchCountStateKey)).ReturnsAsync("0");

            var service = new ShadowModeService(mockSettings.Object, mockState.Object);

            // Act
            var shouldPrompt = await service.ShouldPromptForActivationAsync();

            // Assert
            Assert.True(shouldPrompt);
        }

